// File contracts/helpers/UniERC20.sol

pragma solidity ^0.7.6;

library UniERC20 {
  using SafeMath for uint256;
  using SafeERC20 for IERC20;

  IERC20 private constant _ETH_ADDRESS =
    IERC20(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE);
  IERC20 private constant _ZERO_ADDRESS = IERC20(0);

  function isETH(IERC20 token) internal pure returns (bool) {
    return (token == _ZERO_ADDRESS || token == _ETH_ADDRESS);
  }

  function uniBalanceOf(IERC20 token, address account)
    internal
    view
    returns (uint256)
  {
    if (isETH(token)) {
      return account.balance;
    } else {
      return token.balanceOf(account);
    }
  }

  function uniTransfer(
    IERC20 token,
    address payable to,
    uint256 amount
  ) internal {
    if (amount > 0) {
      if (isETH(token)) {
        to.transfer(amount);
      } else {
        token.safeTransfer(to, amount);
      }
    }
  }

  function uniApprove(
    IERC20 token,
    address to,
    uint256 amount
  ) internal {
    require(!isETH(token), "Approve called on ETH");

    // solhint-disable-next-line avoid-low-level-calls
    (bool success, bytes memory returndata) = address(token).call(
      abi.encodeWithSelector(token.approve.selector, to, amount)
    );

    if (
      !success || (returndata.length > 0 && !abi.decode(returndata, (bool)))
    ) {
      _callOptionalReturn(
        token,
        abi.encodeWithSelector(token.approve.selector, to, 0)
      );
      _callOptionalReturn(
        token,
        abi.encodeWithSelector(token.approve.selector, to, amount)
      );
    }
  }

  function _callOptionalReturn(IERC20 token, bytes memory data) private {
    // solhint-disable-next-line avoid-low-level-calls
    (bool success, bytes memory result) = address(token).call(data);
    if (!success) {
      revert(RevertReasonParser.parse(result, "Low-level call failed: "));
    }

    if (result.length > 0) {
      // Return data is optional
      require(abi.decode(result, (bool)), "ERC20 operation did not succeed");
    }
  }
}

